  snmp_ifOperStatus{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"}
  * on(device_name, ifIndex, snmp_group) group_left(if_Alias) (max by (device_name, ifIndex, if_Alias, snmp_group) (snmp_ifAdminStatus{snmp_group=~"$snmp_group",device_name=~"$instance"})),
  "if_Alias", "—", "if_Alias", "^$"
)

(
  sum by(if_interface_name) (
    sum by(device_name, if_interface_name) (if:snmp_ifHCInOctets:rate5m{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"})
  ) * 8
) or (
  max by(if_interface_name) (snmp_ifOperStatus{snmp_group=~"$snmp_group",device_name=~"$instance", if_interface_name=~"$interface_name"}) * 0
)

(
